using System.Collections.ObjectModel;

namespace TQVaultAE.Domain.Entities;

/// <summary>
/// Record id and allowed gear of each <see cref="RelicAndCharm"/>, read from its attributes.
/// </summary>
/// <remarks>Kept apart from <see cref="RelicAndCharm"/>, which is generated by <c>RegenRelicEnum.ps1</c>.</remarks>
public static class RelicAndCharmExtension
{
	internal record RelicAndCharmMapItem(RelicAndCharm Value, RecordId RecordId, GearType Types);

	internal static readonly ReadOnlyCollection<RelicAndCharmMapItem> RelicAndCharmMap =
		EnumsNET.Enums.GetValues<RelicAndCharm>()
		.Select(v => EnumsNET.Enums.GetMember(v)!)
		.Select(m =>
		{
			var idStr = m.AsString(EnumsNET.EnumFormat.Description)!;
			return new RelicAndCharmMapItem(
				m.Value,
				RecordId: idStr,
				Types: m.Attributes.Get<GearTypeAttribute>()!.Type
			);
		}).ToList().AsReadOnly();

	/// <summary>
	/// Gets the <see cref="GearType"/> for a <see cref="RelicAndCharm"/>
	/// </summary>
	public static GearType GetGearType(this RelicAndCharm relic)
		=> RelicAndCharmMap.First(m => m.Value == relic).Types;

	/// <summary>
	/// Gets the recordId for a <see cref="RelicAndCharm"/>
	/// </summary>
	public static RecordId GetRecordId(this RelicAndCharm relic)
		=> RelicAndCharmMap.First(m => m.Value == relic).RecordId;
}
